pub mod aggregate;

/// Render category totals as "category: total" lines, sorted by category.
pub fn render(csv: &str) -> String {
    aggregate::category_totals(csv)
        .iter()
        .map(|(cat, total)| format!("{}: {}", cat, total))
        .collect::<Vec<_>>()
        .join("\n")
}

