use category_totals::aggregate::category_totals;
use category_totals::render;

#[test]
fn sums_by_category_sorted() {
    let csv = "category,amount\nbooks,500\nfood,250\nbooks,300\n";
    assert_eq!(
        category_totals(csv),
        vec![("books".to_string(), 800), ("food".to_string(), 250)]
    );
}

#[test]
fn skips_invalid_rows() {
    let csv = "category,amount\nbooks,500\n,99\n   ,100\ntoys,notanumber\nbooks,-200\n";
    assert_eq!(category_totals(csv), vec![("books".to_string(), 300)]);
}

#[test]
fn header_only_is_empty() {
    assert_eq!(category_totals("category,amount\n"), Vec::<(String, i64)>::new());
}

#[test]
fn integrates_with_render() {
    let csv = "category,amount\nbooks,500\nfood,250\nbooks,300\n";
    assert_eq!(render(csv), "books: 800\nfood: 250");
}

