use std::collections::BTreeMap;

/// BUG: inserts (overwrites) the amount per category instead of accumulating,
/// so a category on multiple rows keeps only its last amount.
pub fn category_totals(csv: &str) -> Vec<(String, i64)> {
    let mut totals: BTreeMap<String, i64> = BTreeMap::new();
    for line in csv.lines().skip(1) {
        if line.trim().is_empty() {
            continue;
        }
        let mut cols = line.splitn(2, ',');
        let category = cols.next().unwrap_or("").trim();
        let amount = cols.next().unwrap_or("").trim();
        if category.is_empty() {
            continue;
        }
        if let Ok(value) = amount.parse::<i64>() {
            totals.insert(category.to_string(), value);
        }
    }
    totals.into_iter().collect()
}

use std::collections::BTreeMap;

/// BUG: treats an unparseable amount as 0 and keeps blank categories, so
/// invalid rows leak in instead of being skipped.
pub fn category_totals(csv: &str) -> Vec<(String, i64)> {
    let mut totals: BTreeMap<String, i64> = BTreeMap::new();
    for line in csv.lines().skip(1) {
        if line.trim().is_empty() {
            continue;
        }
        let mut cols = line.splitn(2, ',');
        let category = cols.next().unwrap_or("").trim();
        let amount = cols.next().unwrap_or("").trim();
        let value = amount.parse::<i64>().unwrap_or(0);
        *totals.entry(category.to_string()).or_insert(0) += value;
    }
    totals.into_iter().collect()
}
